import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

function checkName(name, line) {
  if (!NAME_RE.test(name)) {
    throw new CliError(`line ${line}: invalid task name ${name}`)
  }
}

/**
 * @param {string} input
 * @returns {{ order: string[], costs: Map<string, number>, deps: Map<string, string[]> }}
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const order = []
  const costs = new Map()
  const deps = new Map()
  const references = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      checkName(name, lineNumber)
      if (!COST_RE.test(costText)) {
        throw new CliError(`line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (costs.has(name)) {
        throw new CliError(`line ${lineNumber}: task ${name} is declared twice`)
      }
      costs.set(name, parseInt(costText, 10))
      order.push(name)
      if (!deps.has(name)) {
        deps.set(name, [])
      }
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const dependencyNames = words.slice(2)
      checkName(name, lineNumber)
      for (const dependencyName of dependencyNames) {
        checkName(dependencyName, lineNumber)
      }
      references.push(name, ...dependencyNames)
      const existing = deps.get(name) ?? []
      const seen = new Set(existing)
      for (const dependencyName of dependencyNames) {
        if (!seen.has(dependencyName)) {
          seen.add(dependencyName)
          existing.push(dependencyName)
        }
      }
      deps.set(name, existing)
    } else {
      throw new CliError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  for (const name of references) {
    if (!costs.has(name)) {
      throw new CliError(`unknown task ${name}`)
    }
  }

  return { order, costs, deps }
}
