 * Graph analysis over a parsed build graph: cycle detection, dependency
 * depth/timing, and scheduling priority.
 */

import { CycleError } from './errors.js'

/**
 * Finds the first cycle a depth-first search encounters when it starts from
 * each task in ascending name order and walks dependencies in ascending
 * name order. Throws `CycleError` if one is found.
 *
 * @param {string[]} names - all task names, ascending.
 * @param {Map<string, string[]>} deps
 */
export function checkForCycle(names, deps) {
  const state = new Map() // name -> 'visiting' | 'done'
  const stack = []

  function visit(name) {
    state.set(name, 'visiting')
    stack.push(name)
    const dependencies = [...(deps.get(name) ?? [])].sort()
    for (const dependency of dependencies) {
      const dependencyState = state.get(dependency)
      if (dependencyState === 'visiting') {
        const start = stack.indexOf(dependency)
        const cycle = [...stack.slice(start), dependency]
        throw new CycleError(cycle)
      }
      if (dependencyState !== 'done') {
        visit(dependency)
      }
    }
    stack.pop()
    state.set(name, 'done')
  }

  for (const name of names) {
    if (!state.has(name)) {
      visit(name)
    }
  }
}

/**
 * Computes, for every task, its dependency depth (wave index), start time
 * and finish time under unlimited workers.
 *
 * @param {string[]} names - all task names, ascending.
 * @param {Map<string, number>} costs
 * @param {Map<string, string[]>} deps
 * @returns {{ depth: Map<string, number>, start: Map<string, number>, finish: Map<string, number> }}
 */
export function computeTiming(names, costs, deps) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function compute(name) {
    if (finish.has(name)) {
      return
    }
    const dependencies = deps.get(name) ?? []
    let taskDepth = 0
    let taskStart = 0
    for (const dependency of dependencies) {
      compute(dependency)
      taskDepth = Math.max(taskDepth, depth.get(dependency) + 1)
      taskStart = Math.max(taskStart, finish.get(dependency))
    }
    depth.set(name, taskDepth)
    start.set(name, taskStart)
    finish.set(name, taskStart + costs.get(name))
  }

  for (const name of names) {
    compute(name)
  }

  return { depth, start, finish }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at
 * it and runs through its dependents down to a task nothing depends on.
 *
 * @param {string[]} names - all task names, ascending.
 * @param {Map<string, number>} costs
 * @param {Map<string, string[]>} deps
 * @returns {Map<string, number>}
 */
export function computePriority(names, costs, deps) {
  const dependents = new Map(names.map((name) => [name, []]))
  for (const name of names) {
    for (const dependency of deps.get(name) ?? []) {
      dependents.get(dependency).push(name)
    }
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) {
      return priority.get(name)
    }
    let best = 0
    for (const dependent of dependents.get(name)) {
      best = Math.max(best, compute(dependent))
    }
    const value = costs.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of names) {
    compute(name)
  }

  return priority
}
"}

